/**
 * Microsoft Teams channel pack for the customer's own Azure Bot.
 *
 * ```ts
 * import { teamsChannel } from "@grok/agent-sdk/channels/teams";
 *
 * // TEAMS_APP_ID + TEAMS_APP_PASSWORD + TEAMS_TENANT_ID
 * export default teamsChannel();
 *
 * // One Azure Bot per agent in a multi-agent serve
 * export default teamsChannel({ envPrefix: "MY_AGENT" });
 * // → MY_AGENT_TEAMS_APP_ID + MY_AGENT_TEAMS_APP_PASSWORD + MY_AGENT_TEAMS_TENANT_ID
 * ```
 */
export { buildTeamsAuthContext, teamsThreadKey } from "./auth.js";
export { teamsCredentialsFromEnv, teamsEnvKeys } from "./credentials.js";
export { defaultTeamsDispatch } from "./dispatch.js";
export { TEAMS_CHANNEL_KIND, teamsChannel } from "./teams-channel.js";
export * from "./types.js";
